// UpdateSysRole 按 opts 收集的 SET / WHERE 组合更新行,返回实际改写行数。
// SET 白名单与 WHERE 定位条件均来自列级 @updatable;有 @pk 时自动附带
// 主键列的定位方法(类型矩阵)。@scope 不参与写面,权限由读取阶段保证。
// 零 SET 或零调用方 WHERE 条件显式拒绝(Kind=set / where),不发全表 UPDATE,
// 也不静默 no-op。
// @filter 不变量恒定 AND 进 WHERE;WithoutFilter() 可整体绕过,但不豁免
// 零 where 守卫。
//
// 参数:
//   - ctx: 更新上下文。
//   - db:  数据库连接,满足 DBTX 接口即可。
//   - opts: SET / WHERE 选项(SysRoleUpdate.*),跨表选项编译期不可混用。
//
// 返回值:
//   - int64: 实际改写行数;0 = 未命中(条件不匹配),不隐式特判。
//   - error: 校验或执行失败时的错误。
func UpdateSysRole(ctx context.Context, db DBTX, opts ...SysRoleUpdateOption) (int64, error) {
	st := dynq.NewUpdateState[SysRoleTable]()
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		if err := opt(st); err != nil {
			return 0, err
		}
	}
	// 空 SET / 零 where 守卫:按调用方条件数计——@filter 叠加后最终 WHERE
	// 恒非空,不得以最终 SQL 形态代替判断。
	if err := st.Validate(); err != nil {
		return 0, err
	}
	conds := make([]sq.Sqlizer, 0, 1+len(st.Wheres()))
	// 恒定条件:@filter 服务端不变量(WithoutFilter 可绕过),与调用方条件 AND。
	if !st.FilterBypassed() {
		conds = append(conds, sq.Expr("deleted_at IS NULL"))
	}
	conds = append(conds, st.Wheres()...)
	b := sq.Update("sys_role").PlaceholderFormat(sq.Dollar).Where(sq.And(conds))
	for _, a := range st.Sets() {
		b = b.Set(a.Column, sq.Expr("?"+a.Cast, a.Value))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return 0, err
	}
	tag, err := db.Exec(ctx, query, args...)
	if err != nil {
		return 0, err
	}
	return tag.RowsAffected(), nil
}

// SysRoleQuerySchema 是前端契约出口:返回经 opts 减法投影后的有效能力全集,
// 前端据此渲染查询组件。Schema 是(生成期元数据, opts)的确定性纯函数,
// 同一 opts 产出字节级相同结果,内容 hash 可作 ETag;被禁用字段不出现于 schema。
//
