//
// 返回值:
//   - dynq.ResourceSchema: 前端渲染所需的能力描述(字段、操作符、排序、分页配置)。
func SysRoleQuerySchema(opts ...dynq.QueryOption) dynq.ResourceSchema {
	cfg, err := dynq.NewQueryConfig(sys_roleRegistry, opts...)
	if err != nil {
		// 禁用目标不在 registry 属于编程错误。Parse/List/Count/Schema 四点同参纪律
		// 下,此处 panic 显式暴露;静默吞错会掩盖权限收窄失效。
		panic(err)
	}
	return dynq.BuildSchema(sys_roleRegistry, cfg)
}
